@'
import fs from 'node:fs';
const file = 'src/core.js';
const text = fs.readFileSync(file, 'utf8');
const old = 'Checkpoint unfinished work before handing off. Never mark a task verified';
const replacement = 'Before finishing, review prose checkpoints too: remaining entries classify required work (blocks finish), follow_up (existing taskId), verification_limit or out_of_scope. Pass [] for an explicit empty review; omission is unreviewed. A limit cannot waive a required criterion. Checkpoint unfinished work before handing off. Never mark a task verified';
if (!text.includes(old)) throw new Error('Instruction anchor missing');
fs.writeFileSync(file, text.replace(old, replacement));
const mcp = 'src/mcp.js';
let source = fs.readFileSync(mcp, 'utf8');
const { execFileSync } = await import('node:child_process');
const before = execFileSync('git', ['show', 'HEAD:src/mcp.js'], {encoding:'utf8', windowsHide:true});
source = source.replace(/import \{ semanticEnabled, semanticRetrieve \} from "\.\/semantic.js";/, before.match(/import .* from '.\/semantic.js';/)[0]);
const start = source.indexOf('  if (semanticEnabled())');
const end = source.indexOf('  add(\n    "task_get"', start);
const originalStart = before.indexOf('  if(semanticEnabled())');
const originalEnd = before.indexOf('  add(\n    "task_get"', originalStart);
fs.writeFileSync(mcp, source.slice(0,start) + before.slice(originalStart,originalEnd) + source.slice(end));
'@ | node --input-type=module
node node_modules/prettier/bin/prettier.cjs --write src/health.js test/accuracy.test.js src/core.js
node --test test/accuracy.test.js
